parameters.jsCode:
const msg = $input.first().json;
const text = msg.text || msg.message?.text || '';

// Extract LinkedIn post from between the markers
const linkedinMatch = text.match(/\*--- LinkedIn Post ---\*\n\n([\s\S]*?)\n\n\*--- X \/ Twitter Post ---\*/); 
const linkedinText = linkedinMatch ? linkedinMatch[1].trim() : '';

// Extract hashtags line
const hashtagMatch = text.match(/_Hashtags:_ (.+)/);
const hashtags = hashtagMatch ? hashtagMatch[1].trim() : '';

// Extract X post
const xMatch = text.match(/\*--- X \/ Twitter Post ---\*\n\n([\s\S]*?)\n\n(?:_Thread:|\*Notes:|━)/);
const xText = xMatch ? xMatch[1].trim() : '';

return [{
  json: {
    linkedin_text: linkedinText + (hashtags ? '\n\n' + hashtags : ''),
    x_text: xText,
    channel: msg.channel || $('Slack Reaction Trigger').first().json.event?.item?.channel,
    original_ts: msg.ts || $('Slack Reaction Trigger').first().json.event?.item?.ts
  }
}];

